using UnityEditor;using UnityEngine;using System.IO;public static class BrowserProjectPort {public static void Prepare(){Directory.CreateDirectory("Assets/Resources");const string path="Assets/Resources/BrowserProjectile.mat";var shader=Shader.Find("Portfolio/BrowserProjectile");if(shader==null)throw new System.Exception("Browser projectile shader missing");var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing==null){existing=new Material(shader);AssetDatabase.CreateAsset(existing,path);}else existing.shader=shader;existing.enableInstancing=true;var graphics=AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/GraphicsSettings.asset");if(graphics.Length>0){var so=new SerializedObject(graphics[0]);var shaders=so.FindProperty("m_AlwaysIncludedShaders");bool found=false;for(int i=0;i<shaders.arraySize;i++)if(shaders.GetArrayElementAtIndex(i).objectReferenceValue==shader)found=true;if(!found){int n=shaders.arraySize;shaders.InsertArrayElementAtIndex(n);shaders.GetArrayElementAtIndex(n).objectReferenceValue=shader;so.ApplyModifiedPropertiesWithoutUndo();}}AssetDatabase.SaveAssets();}}